import os,json,time,datetime
from pathlib import Path
root=49
ppids={}
for p in Path('/proc').iterdir():
 if p.name.isdigit():
  try:
   status=(p/'status').read_text()
   ppid=int(next(x.split()[1] for x in status.splitlines() if x.startswith('PPid:')))
   ppids[int(p.name)]=ppid
  except (OSError,StopIteration,ValueError):pass
wanted={root}
while True:
 added={p for p,parent in ppids.items() if parent in wanted}-wanted
 if not added:break
 wanted.update(added)
procs=[]
for pid in sorted(wanted):
 p=Path('/proc')/str(pid);entry={'pid':pid}
 try:
  stat=(p/'stat').read_text();v=stat[stat.rfind(')')+2:].split()
  entry.update(stat_raw=stat,state=v[0],ppid=int(v[1]),pgrp=int(v[2]),utime_ticks=int(v[11]),stime_ticks=int(v[12]),cutime_ticks=int(v[13]),cstime_ticks=int(v[14]),starttime_ticks=int(v[19]),rss_pages=int(v[21]))
  entry['cmdline']=(p/'cmdline').read_bytes().replace(bytes([0]),b' ').decode('utf-8','backslashreplace')
  for name in ['status','io','wchan','schedstat']:
   try:entry[name]=(p/name).read_text()
   except OSError as e:entry[name+'_read_error']=str(e)
 except OSError as e:entry['read_error']=str(e)
 procs.append(entry)
print(json.dumps({'observed_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'clock_ticks_per_second':os.sysconf('SC_CLK_TCK'),'page_size':os.sysconf('SC_PAGE_SIZE'),'uptime_seconds':float(Path('/proc/uptime').read_text().split()[0]),'root_pid':root,'processes':procs}))
